def pack_order(
    order_id: str,
    quantities: Mapping[str, int],
    products: Mapping[str, Product],
) -> list[Parcel]:
    """Pack an order into parcels, first fit, heaviest units first.

    No parcel may weigh more than MAX_PARCEL_KG; a single unit over that limit
    raises ValueError.
    """
    parcels: list[Parcel] = []
    for sku in sorted(quantities, key=lambda code: products[code].weight_kg, reverse=True):
        weight = products[sku].weight_kg
        if weight > MAX_PARCEL_KG:
            raise ValueError(f"{sku} is too heavy to ship as a parcel")
        for _ in range(quantities[sku]):
            for parcel in parcels:
                if parcel.weight_kg + weight <= MAX_PARCEL_KG:
                    parcel.weight_kg += weight
                    if sku in parcel.items:
                        parcel.items[sku] += 1
                    else:
                        parcel.items[sku] = 1
                    break
            else:
                parcels.append(Parcel(order_id, weight, {sku: 1}))
    return parcels

def _take_from_bins(line: CustomerLine, bins: dict[str, int]) -> list[PickTask]:
    """Pick tasks that cover ``line`` from ``bins``, lowering ``bins`` as it goes."""
    if sum(bins.values()) < line.quantity:
        raise InsufficientStock(f"not enough {line.sku} in the bins for order {line.order_id}")
    needed = line.quantity
    tasks = []
    for bin_code in sorted(bins, key=lambda code: (bins[code], code)):
        take = min(needed, bins[bin_code])
        if take > 0:
            bins[bin_code] -= take
            needed -= take
            tasks.append(PickTask(line.order_id, line.sku, bin_code, take))
    return tasks

