from typing import Mapping

MAX_PARCEL_KG = 10  # Example value for MAX_PARCEL_KG

class Parcel:
    def __init__(self, order_id: str, weight_kg: float, items: Mapping[str, int]):
        self.order_id = order_id
        self.weight_kg = weight_kg
        self.items = items

def pack_order(
    order_id: str,
    quantities: Mapping[str, int],
    products: Mapping[str, Product],
) -> list[Parcel]:
    """Pack an order into parcels, first fit, heaviest units first.

    No parcel may weigh more than MAX_PARCEL_KG; a single unit over that limit
    raises ValueError.
    """
    parcels: list[Parcel] = []
    for sku in sorted(quantities, key=lambda code: products[code].weight_kg, reverse=True):
        weight = products[sku].weight_kg
        if weight > MAX_PARCEL_KG:
            raise ValueError(f"{sku} is too heavy to ship as a parcel")
        for _ in range(quantities[sku]):
            for parcel in parcels:
                if parcel.weight_kg + weight <= MAX_PARCEL_KG:
                    parcel.weight_kg += weight
                    if sku in parcel.items:
                        parcel.items[sku] += 1
                    else:
                        parcel.items[sku] = 1
                    break
            else:
                parcels.append(Parcel(order_id, weight, {sku: 1}))
    return parcels
```

Explanation: The else block in the original code was incorrectly appending a new parcel when no parcel could accommodate the new item. It should only append a new parcel if the item cannot fit into any existing parcel. The fix ensures that the else block correctly handles the case where no parcel can accommodate the new item by appending a new parcel only when the item cannot fit into any existing parcel.

